470	func deleteUserInClause[T any](start int, values []T) (string, []any) {
471		placeholders := make([]string, 0, len(values))
472		args := make([]any, 0, len(values))
473		for i, value := range values {
474			placeholders = append(placeholders, deleteUserPlaceholder(start+i))
475			args = append(args, value)
476		}
477		return "(" + strings.Join(placeholders, ", ") + ")", args
478	}
479	
480	func deleteUserBatches[T any](values []T, size int) [][]T {
481		if len(values) == 0 {
482			return nil
483		}
484		if size <= 0 {
485			size = len(values)
486		}
487	
488		batches := make([][]T, 0, (len(values)+size-1)/size)
489		for start := 0; start < len(values); start += size {
490			end := min(start+size, len(values))
491			batches = append(batches, values[start:end])
492		}
493		return batches
494	}
